const http = require('http')

const server = http.createServer((req, res) => {
  if (req.url === '/hello') {
    res.writeHead(200, {'Content-Type': 'application/json'})
    res.end(JSON.stringify({message: 'hello'}))
    return
  }
  res.writeHead(404)
  res.end('not found')
})

server.listen(8899, '127.0.0.1', () => console.log('up on 8899'))
